input.sparql:
SELECT ?s ?iri ?class WHERE {
  ?s a brick:Core_Zone . 
  OPTIONAL { ?s rdfs:label ?l }
  ?ts ref:hasTimeseriesId ?iri .
  ?ts brick:hasParent ?s .
  OPTIONAL { ?ts a ?class }
}

SELECT ?p ?class ?l ?tsid WHERE {
  ?p ?rel ?zoneOrThing .
  ?p brick:hasParent* ?zone .
  FILTER(?zone = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01>)
  OPTIONAL { ?p a ?class }
  OPTIONAL { ?p rdfs:label ?l }
  OPTIONAL { ?ser ref:hasTimeseriesId ?tsid . FILTER(?p = ?ser) }
  OPTIONAL { ?p ref:hasTimestamp ?tsid }
  ?p ?pred ?x .
}

SELECT ?p ?class ?tsid WHERE {
  ?p brick:hasParent+ ?zone .
  FILTER(?zone = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01>)
  ?p a ?class .
  ?p ref:hasTimeseriesId ?tsid .
}

SELECT ?p ?class ?tsid WHERE {
  ?z brick:hasPoint ?p .
  FILTER(?z = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01>)
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}
